function getOnlineTemplate(id) {
  return ONLINE_TEMPLATES.find((item) => item.id === id) || null;
}
function buildOnlineDocument(id) {
  const item = getOnlineTemplate(id);
  if (!item || !item.document) return null;
  return JSON.parse(JSON.stringify(item.document));
}
module.exports = { ONLINE_TEMPLATES, getOnlineTemplate, buildOnlineDocument };
